/*
	VIOC ew_drones (solo servidor): inhibidores de drones en soldados concretos de la IA.
	- Usa la mochila "Drone Jammer Pack" (DDT_BackpackJammer; nombre viejo DDT_DroneJammerPack) del mod Drongo's Drone
	  Tweaks y su funcion DDT_fnc_JammerPack: a pie, cada 3 s, 90 por ciento de probabilidad de tumbar cada dron ENEMIGO a
	  menos de 100 m (desconecta la terminal y el dron cae). No toca los drones de su propio bando.
	- El mod trae apagado su registro de portadores (Scripts\Jammers\Register.sqf comentado en Start.sqf): este archivo
	  agrega la mochila a ddtJammers y arranca DDT_fnc_JammerPack para cada portador nuestro que este a pie (la funcion
	  termina si sube a un vehiculo; al bajar se vuelve a arrancar, cada VIOC_EW_REG s).
	- Parametro VIOC_EW_JAMMERS: porcentaje de escuadras IA del oeste y del este (6 o mas hombres vivos) que llevan UN
	  inhibidor; 0 = ninguno. Cada escuadra se sortea una sola vez (si el portador muere, no se repone).
	- El portador es un soldado sin mochila o con una mochila vacia y comun: nunca el jefe, un jugador, el operador de un
	  dron FPV (vioc_fpv), ni quien lleva radio de largo alcance, arma estatica, dron, paracaidas o cosas en la mochila.
	- Nunca el grupo de un jugador.
	- Consola (servidor): hint (call VIOC_EW_fnc_info);
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_EW_LOADED") exitWith {};
VIOC_EW_LOADED = true;

VIOC_EW_BAG = (["DDT_BackpackJammer", "DDT_DroneJammerPack"] select {isClass (configFile >> "CfgVehicles" >> _x)}) param [0, ""];
VIOC_EW_PCT = missionNamespace getVariable ["VIOC_EW_JAMMERS", 50];
if !(VIOC_EW_PCT isEqualType 0) then {VIOC_EW_PCT = 50};
VIOC_EW_MIN = 6;			//--- hombres vivos para que la escuadra entre en el sorteo
VIOC_EW_TICK = 45;			//--- s entre sorteos de escuadras
VIOC_EW_REG = 15;			//--- s entre arranques de DDT_fnc_JammerPack para los portadores a pie
VIOC_EW_STAT = [0, 0, 0];	//--- [escuadras sorteadas, con inhibidor, elegidas pero sin portador posible]
VIOC_EW_STATE = "esperando";

VIOC_EW_fnc_log = {diag_log format ["VIOC_ew_drones: %1", _this]};

//--- [unidad] -> true si puede cambiar su mochila por la del inhibidor (misma regla que el reparto de drones FPV)
VIOC_EW_fnc_bagOk = {
	params ["_u"];
	private _bp = backpack _u;
	if (_bp == "") exitWith {true};
	private _cfg = configFile >> "CfgVehicles" >> _bp;
	((backpackItems _u) isEqualTo []) && {(getNumber (_cfg >> "maximumLoad")) > 0} && {!(_bp isKindOf "Weapon_Bag_Base")} &&
		{(getText (_cfg >> "assembleInfo" >> "assembleTo")) == ""} && {(getText (_cfg >> "ParachuteClass")) == ""} &&
		{(getNumber (_cfg >> "tf_hasLRradio")) == 0} && {((toLower _bp) find "crocus") < 0} && {((toLower _bp) find "jammer") < 0}
};

//--- [grupo] -> true si un soldado del grupo quedo con el inhibidor
VIOC_EW_fnc_give = {
	params ["_g"];
	private _men = (units _g) select {
		alive _x && {!isPlayer _x} && {_x != leader _g} && {_x isKindOf "CAManBase"} && {isNil {_x getVariable "vioc_fpv"}} && {[_x] call VIOC_EW_fnc_bagOk}
	};
	if (count _men == 0) exitWith {false};
	private _u = selectRandom _men;
	private _old = backpack _u;
	if (_old != "") then {removeBackpackGlobal _u};
	_u addBackpackGlobal VIOC_EW_BAG;
	if ((backpack _u) != VIOC_EW_BAG) exitWith {
		if (_old != "" && {(backpack _u) == ""}) then {_u addBackpackGlobal _old};
		false
	};
	_u setVariable ["vioc_jammer", true, true];
	true
};

VIOC_EW_fnc_info = {
	private _j = allUnits select {alive _x && {(backpack _x) == VIOC_EW_BAG}};
	format ["VIOC ew_drones: %1 por ciento de escuadras (%2) | sorteadas %3, con inhibidor %4, sin portador %5 | vivos ahora: oeste %6, este %7, otros %8",
		VIOC_EW_PCT, VIOC_EW_STATE, VIOC_EW_STAT select 0, VIOC_EW_STAT select 1, VIOC_EW_STAT select 2,
		{(side group _x) == west} count _j, {(side group _x) == east} count _j, {!((side group _x) in [west, east])} count _j]
};

if (VIOC_EW_PCT <= 0) exitWith {VIOC_EW_STATE = "apagado en el lobby"; "apagado (VIOC_EW_JAMMERS = 0)" call VIOC_EW_fnc_log};
if (VIOC_EW_BAG == "") exitWith {VIOC_EW_STATE = "falta el mod Drongo's Drone Tweaks"; "sin la mochila DDT_BackpackJammer (falta Drongo's Drone Tweaks)" call VIOC_EW_fnc_log};

[] spawn {
	sleep 60;
	//--- funcion del mod que hace el trabajo; la lista ddtJammers (la define el mod) debe tener nuestra mochila
	private _t = time + 300;
	waitUntil {sleep 5; (!isNil "DDT_fnc_JammerPack") || {time > _t}};
	if (isNil "DDT_fnc_JammerPack") exitWith {
		VIOC_EW_STATE = "falta DDT_fnc_JammerPack (Drongo's Drone Tweaks)";
		"sin DDT_fnc_JammerPack: sin inhibidores" call VIOC_EW_fnc_log;
	};
	if (isNil "ddtJammers" || {!(ddtJammers isEqualType [])}) then {ddtJammers = []};
	ddtJammers pushBackUnique VIOC_EW_BAG;
	VIOC_EW_STATE = "activo";
	format ["activo: %1 por ciento de las escuadras de %2 o mas, mochila %3", VIOC_EW_PCT, VIOC_EW_MIN, VIOC_EW_BAG] call VIOC_EW_fnc_log;
	private _next = 0;
	while {true} do {
		//--- portadores a pie sin la funcion del mod en marcha (ddtReg lo pone el mod en false al terminar)
		{
			if (alive _x && {_x getVariable ["vioc_jammer", false]} && {isNull objectParent _x} && {(backpack _x) == VIOC_EW_BAG} && {!(_x getVariable ["ddtReg", false])}) then {
				_x setVariable ["ddtReg", true, true];
				[_x] spawn DDT_fnc_JammerPack;
			};
		} forEach allUnits;
		if (time >= _next) then {
		_next = time + VIOC_EW_TICK;
		{
			private _g = _x;
			if ((side _g) in [west, east] && {isNil {_g getVariable "vioc_ew"}} && {!isNull (leader _g)} && {!isPlayer (leader _g)} &&
				{((units _g) findIf {isPlayer _x}) < 0} && {({alive _x && {_x isKindOf "CAManBase"}} count (units _g)) >= VIOC_EW_MIN}) then {
				VIOC_EW_STAT set [0, (VIOC_EW_STAT select 0) + 1];
				private _yes = (random 100) < VIOC_EW_PCT;
				_g setVariable ["vioc_ew", _yes];
				if (_yes) then {
					if ([_g] call VIOC_EW_fnc_give) then {VIOC_EW_STAT set [1, (VIOC_EW_STAT select 1) + 1]} else {VIOC_EW_STAT set [2, (VIOC_EW_STAT select 2) + 1]};
				};
			};
		} forEach allGroups;
		};
		sleep VIOC_EW_REG;
	};
};

//--- VIOC ew_escort: antena repetidora de drones FPV ("FPV Signal Booster", mod ArmaFPV). A menos de 1,5 km del dron o
//--- del piloto: +2,5 km de alcance y mucha menos perdida de senal detras de colinas. Categoria propia "Drones" (la IA
//--- comandante no la compra). Parametro VIOC_FPV_BOOSTER.
if ((missionNamespace getVariable ["VIOC_FPV_BOOSTER", 1]) isEqualTo 1 && {isClass (configFile >> "CfgVehicles" >> "FPV_Retranslator")}) then {
	_headers pushBack "FPV Signal Booster (antena de drones)";
	_classes pushBack "FPV_Retranslator";
	_prices pushBack ([CTI_ECONOMY_PRIZE_EQUIPMENT, 0, false, 5] call CTI_CO_FNC_GetCalculatedUnitsPrize);
	_placements pushBack [0, 10];
	_categories pushBack "Drones";
	_tiers pushBack 0;
};

class VIOC_EW_JAMMERS {
	title = "VIOC drones: Inhibidores en escuadras IA (oeste y este, de 6 o mas; mochila Drone Jammer Pack de Drongo: tumba drones enemigos a menos de 100 m)";
	values[] = {0,25,50,100};
	texts[] = {"No","25 por ciento de las escuadras","50 por ciento de las escuadras","Todas"};
	default = 50;
};
class VIOC_FPV_BOOSTER {
	title = "VIOC drones: Antena repetidora FPV en el menu de construccion (FPV Signal Booster: +2.5 km de alcance y menos perdida de senal a menos de 1.5 km)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
class VIOC_SO_ESCORT {
	title = "VIOC: Operaciones especiales: escolta de helicoptero de ataque en las inserciones en helicoptero y Little Bird";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};

//--- VIOC ew_escort: escolta de las inserciones en helicoptero y Little Bird (jugadores e IA; parametro VIOC_SO_ESCORT). Un
//--- helicoptero de ataque del bando (tabla de escoltas de VIOC_air_assault.sqf: EE. UU. AH-64D; Colombia Arpia IV;
//--- Rusia Ka-52 o Mi-24) sale junto al transporte, va a la zona de aterrizaje y da vueltas atacando lo que ve hasta
//--- VIOC_SO_ESC_STAY s despues de que el transporte aterrice (o caiga) a menos de 900 m, o hasta que se vaya sin
//--- aterrizar; 8 min como mucho sobre la zona. Sale siempre, aunque el bando no tenga desbloqueado el helicoptero de ataque. Luego vuelve y se borra lejos de los jugadores (VIOC_AA_fnc_airGone). Sin coste extra.
//--- Si no hay clase o no sale: la operacion sigue sin escolta.
VIOC_SO_ESCORT_ON = (missionNamespace getVariable ["VIOC_SO_ESCORT", 1]) isEqualTo 1;
VIOC_SO_ESC_STAY = 150;
VIOC_SO_ESC_ALT = 120;
VIOC_SO_ESC_R = 450;
VIOC_SO_ESC_N = 0;	//--- escoltas que salieron (consola)

//--- [bando] -> clase de la escolta o ""
VIOC_fnc_soEscortClass = {
	params ["_side"];
	if (isNil "VIOC_AA_TABLE" || {isNil "VIOC_AA_fnc_nation"} || {isNil "VIOC_AA_fnc_airOk"}) exitWith {""};
	([_side] call VIOC_AA_fnc_nation) params ["_tag", "_mod"];
	private _best = [];
	private _bs = -1;
	{
		_x params ["_r", "_t", "_m", "_cw", "_cd", "_gates"];
		if (_r == "esc" && {(_t == _tag) || {(_tag == "COL") && {_t == "US"}}}) then {
			private _ok = ([_cw] + _gates) select {[_x, _side] call VIOC_AA_fnc_airOk};
			if (count _ok > 0) then {
				private _s = ([0, 2] select (_t == _tag)) + ([0, 1] select (_m == _mod));
				if (_s > _bs) then {_bs = _s; _best = []};
				if (_s == _bs) then {_best pushBack (_ok select 0)};
			};
		};
	} forEach VIOC_AA_TABLE;
	if (count _best == 0) exitWith {""};
	selectRandom _best
};

//--- [operacion, transporte, bando, salida, zona de aterrizaje] (spawn)
VIOC_fnc_soEscort = {
	params ["_op", "_veh", "_side", "_start", "_lz"];
	if (isNil "VIOC_AA_fnc_spawnAir" || {isNil "VIOC_AA_fnc_airGone"} || {isNil "VIOC_AA_fnc_clearWp"}) exitWith {"escolta: falta VIOC_air_assault.sqf" call VIOC_fnc_soLog};
	private _cls = [_side] call VIOC_fnc_soEscortClass;
	if (_cls == "") exitWith {format ["escolta: %1 no tiene helicoptero de ataque", _side] call VIOC_fnc_soLog};
	private _p0 = [_start getPos [250, (_start getDir _lz) + 90]] call VIOC_fnc_soClamp;
	private _air = [_side, _cls, _p0, _p0 getDir _lz, VIOC_SO_ESC_ALT] call VIOC_AA_fnc_spawnAir;
	if (_air isEqualType "") exitWith {format ["escolta: no salio %1 (%2)", _cls, _air] call VIOC_fnc_soLog};
	_air params ["_ev", "_eg"];
	VIOC_SO_ESC_N = VIOC_SO_ESC_N + 1;
	{_x setVariable ["vioc_aa", nil]; _x setVariable ["vioc_specops", true, true]} forEach (crew _ev);	//--- no cuenta para el tope de hombres de los asaltos aereos
	_op set ["escV", _ev];
	_eg setBehaviour "AWARE";
	_eg setCombatMode "RED";
	_ev flyInHeight VIOC_SO_ESC_ALT;
	private _wp = _eg addWaypoint [_lz, 0];
	_wp setWaypointType "LOITER";
	_wp setWaypointLoiterRadius VIOC_SO_ESC_R;
	_wp setWaypointLoiterType "CIRCLE";
	_wp setWaypointBehaviour "AWARE";
	_wp setWaypointCombatMode "RED";
	_eg setCurrentWaypoint _wp;
	format ["escolta: %1 (%2) acompania al transporte %3", _cls, _side, typeOf _veh] call VIOC_fnc_soLog;
	private _t0 = time;
	private _tArr = -1;
	private _tLand = -1;
	private _near = false;
	waitUntil {
		sleep 3;
		if (_tArr < 0 && {(_ev distance2D _lz) < 900}) then {_tArr = time};
		if (alive _veh && {(_veh distance2D _lz) < 900}) then {_near = true};
		if (_tLand < 0 && {!alive _veh || {!canMove _veh} || {((_veh distance2D _lz) < 900) && {(isTouchingGround _veh) || {((getPosATL _veh) select 2) < 3}}}}) then {_tLand = time};
		!alive _ev || {!canMove _ev} || {!alive (driver _ev)} || {(fuel _ev) < 0.2} || {(damage _ev) > 0.6}
			|| {(_tLand > 0) && {time > (_tLand + VIOC_SO_ESC_STAY)}}
			|| {(_tLand < 0) && {_near} && {alive _veh} && {(_veh distance2D _lz) > 1500}}
			|| {(_tArr > 0) && {time > (_tArr + 480)}}
			|| {time > (_t0 + 1200)}
	};
	if (alive _ev && {canMove _ev} && {alive (driver _ev)}) then {
		[_eg] call VIOC_AA_fnc_clearWp;
		_eg setBehaviour "CARELESS";
		_eg setCombatMode "BLUE";
		_ev flyInHeight 150;
		private _w2 = _eg addWaypoint [_start, 0];
		_w2 setWaypointType "MOVE";
		_eg setCurrentWaypoint _w2;
	};
	format ["escolta: %1 (%2) termina tras %3 s (viva %4)", _cls, _side, round (time - _t0), alive _ev] call VIOC_fnc_soLog;
	[_ev, _eg, _start, _lz getDir _start] call VIOC_AA_fnc_airGone;
};
